<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, type Page } from './api'
defineProps<{ manager: boolean }>()
const emit = defineEmits<{ navigate: [target: string] }>()
interface Notice { id: string; eventType: string; externalOrder?: string; orderId?: string; jobId?: string; createdAt: string; readAt?: string; version: number }
interface Delivery { id: string; eventType: string; status: string; attempts: number; errorCode?: string; version: number }
const rows = ref<Notice[]>([]), deliveries = ref<Delivery[]>([]), page = ref(1), deliveryPage = ref(1), total = ref(0), deliveryTotal = ref(0), count = ref(0), unread = ref(false), busy = ref(false), tab = ref('inbox')
const titles: Record<string, string> = { 'confirmation.submitted': '供应商提交确认', 'confirmation.effective': '订单确认已生效', 'confirmation.rejected': '订单确认未获批准', 'delivery-change.submitted': '交期变更待审批', 'delivery-change.approved': '交期变更已批准', 'delivery-change.rejected': '交期变更已拒绝', 'delivery-change.withdrawn': '交期变更已撤回', 'delivery-plan.planned': '交货计划已生成', 'asn.submitted': 'ASN 已提交', 'asn.cancelled': 'ASN 已取消', 'order.collaboration.superseded': '来源版本更新，旧协同已失效', 'order.conflict': '订单一致性异常，请核对', 'sync.failed': '同步任务失败，请查看同步监控' }
const states: Record<string, string> = { PENDING: '等待投递', DELIVERED: '已完成', FAILED: '失败待重试', SUPERSEDED: '来源已失效' }
async function run(action: () => Promise<void>) { busy.value = true; try { await action() } catch (e) { rows.value = []; deliveries.value = []; count.value = 0; ElMessage.error(e instanceof Error ? e.message : '操作失败') } finally { busy.value = false } }
async function load() {
 if (tab.value === 'inbox') { const r = await api<Page<Notice>>(`/notifications?page=${page.value - 1}&size=20&unread=${unread.value}`); rows.value = r.items; total.value = r.total; count.value = (await api<{ count: number }>('/notifications/unread-count')).count }
 else { const r = await api<Page<Delivery>>(`/notification-deliveries?page=${deliveryPage.value - 1}&size=20`); deliveries.value = r.items; deliveryTotal.value = r.total }
}
async function read(n: Notice) { await api(`/notifications/${n.id}/read`, 'POST', undefined, n.version); await load() }
async function retry(d: Delivery) { await api(`/notification-deliveries/${d.id}/retry`, 'POST', undefined, d.version); await load(); ElMessage.success('已安排重新投递') }
onMounted(() => run(load))
</script>
<template><section class="card"><h2>站内通知</h2><el-tabs v-model="tab" @tab-change="run(load)"><el-tab-pane label="我的通知" name="inbox"><p>未读通知：<strong>{{ count }}</strong></p><el-checkbox v-model="unread" @change="page = 1; run(load)">只看未读</el-checkbox><el-button :loading="busy" :disabled="busy" @click="run(load)">刷新通知</el-button><el-table :data="rows" empty-text="当前没有可见通知"><el-table-column label="事项"><template #default="{ row }">{{ titles[row.eventType] || row.eventType }}</template></el-table-column><el-table-column prop="externalOrder" label="关联订单"/><el-table-column label="时间"><template #default="{ row }">{{ new Date(row.createdAt).toLocaleString() }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ row.readAt ? '已读' : '未读' }}</template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button @click="emit('navigate', row.orderId ? 'orders' : 'sync')">{{ row.orderId ? '查看订单' : '查看同步' }}</el-button><el-button v-if="!row.readAt" :disabled="busy" @click="run(() => read(row))">标为已读</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="run(load)"/></el-tab-pane><el-tab-pane v-if="manager" label="投递监控" name="deliveries"><p class="muted">仅显示你有业务范围权限的内部事件。失败自动退避重试，达到上限后可按版本重新安排。</p><el-button :disabled="busy" @click="run(load)">刷新投递</el-button><el-table :data="deliveries" empty-text="当前没有可见投递"><el-table-column label="事项"><template #default="{ row }">{{ titles[row.eventType] || row.eventType }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ states[row.status] }}</template></el-table-column><el-table-column prop="attempts" label="本轮尝试"/><el-table-column prop="errorCode" label="错误码"/><el-table-column label="操作"><template #default="{ row }"><el-button v-if="row.status === 'FAILED'" :disabled="busy" @click="run(() => retry(row))">重试投递</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="deliveryPage" :total="deliveryTotal" :page-size="20" layout="prev,pager,next,total" @current-change="run(load)"/></el-tab-pane></el-tabs></section></template>
